    (743,5,"Conjure Ice Beast IX","Conjuration","Creation","Cold","V, S, DF",
    "1 round","Close","One or more conjured ice creatures, no two of which can be more than 30 ft. apart",null,"1 round/level (D)",
    "None","No",
    "Conjures ice creature to fight for you.",
